import {sendKeys} from '@web/test-runner-commands';
import {html, render, type ReactiveElement, type TemplateResult} from 'lit';
import './md-gb-nav-rail.js';
import './md-gb-nav-rail-item.js';

let container: HTMLElement | undefined;

async function mount(template: TemplateResult) {
  container?.remove();
  container = document.createElement('div');
  document.body.appendChild(container);
  render(template, container);
  await settle();
  return container;
}

/** Waits for Lit updates and a frame. */
async function settle(root: ParentNode = document.body) {
  for (const el of root.querySelectorAll('*')) {
    const update = (el as Partial<ReactiveElement>).updateComplete;
    if (update) await update;
    if (el.shadowRoot) await settle(el.shadowRoot);
  }
  if (root !== document.body) return;
  await new Promise((resolve) => requestAnimationFrame(resolve));
}

/** Presses a key (or a chord such as `Shift+Tab`) on a real keyboard. */
async function press(key: string) {
  await sendKeys({press: key});
  await settle();
}

/** Dispatches a pointer event with a given `timeStamp` (ms). */
function dsPointer(target: EventTarget, type: string, x: number, y: number, time: number) {
  const event = new PointerEvent(type, {
    bubbles: true,
    composed: true,
    cancelable: true,
    pointerId: 7,
    pointerType: 'touch',
    isPrimary: true,
    button: 0,
    clientX: x,
    clientY: y,
  });
  Object.defineProperty(event, 'timeStamp', {value: time});
  target.dispatchEvent(event);
}

function dsCenter(element: Element) {
  const rect = element.getBoundingClientRect();
  return {x: rect.left + rect.width / 2, y: rect.top + rect.height / 2};
}

/**
 * Presses the center of `target`, moves `dx` along x in `steps` moves and
 * releases (axis y moves along y instead). Slow by default (50ms per step); `fast` flings (2ms per step).
 */
function dsDrag(
  target: Element,
  dx: number,
  {release = true, fast = false, steps = 4, axis = 'x'}: {release?: boolean; fast?: boolean; steps?: number; axis?: 'x' | 'y'} = {},
) {
  const {x, y} = dsCenter(target);
  const ms = fast ? 2 : 50;
  dsPointer(target, 'pointerdown', x, y, 0);
  for (let i = 1; i <= steps; i++) {
    const d = (dx * i) / steps;
    dsPointer(target, 'pointermove', axis === 'y' ? x : x + d, axis === 'y' ? y + d : y, ms * i);
  }
  if (release) dsPointer(target, 'pointerup', axis === 'y' ? x : x + dx, axis === 'y' ? y + dx : y, ms * steps + (fast ? 0 : 500));
}

let dsTokens = false;
const dsExtra: HTMLElement[] = [];

/** Adopts the M3 tokens (once) so motion tokens and component styles resolve. */
async function dsLoadTokens() {
  if (dsTokens) return;
  dsTokens = true;
  const [{adoptStyles}, {styles}] = await Promise.all([
    import('../../styles/adopt-styles.js'),
    import('../../styles/m3.cssresult.js'),
  ]);
  adoptStyles(document, [styles]);
}

async function dsMount(markup: string, selector: string) {
  await dsLoadTokens();
  const host = document.createElement('div');
  host.innerHTML = markup;
  document.body.appendChild(host);
  await settle();
  dsExtra.push(host);
  return host.querySelector<HTMLElement>(selector)!;
}
void dsMount; // Not every component uses it.

async function dsSetup(template: TemplateResult, selector: string) {
  await dsLoadTokens();
  const root = await mount(template);

  const el = root.querySelector<HTMLElement>(selector)! as HTMLElement & {expanded: boolean; open: boolean; revealed: string | null; items: HTMLElement[]; paneWidth: number | null; collapsedPane: string | null; state: string; selectedIndex: number; panels: HTMLElement[]; show(): Promise<void>};
  return {root, el};
}

/** Runs `fn` with reduced motion preferred, then restores the preference. */
async function dsReduceMotion(fn: () => Promise<void>) {
  const {emulateMedia} = await import('@web/test-runner-commands');
  await emulateMedia({reducedMotion: 'reduce'});
  try {
    await fn();
  } finally {
    await emulateMedia({reducedMotion: 'no-preference'});
  }
}


describe('<md-gb-nav-rail> drag and settle contract (DragSettleController: follows the pointer, settles at an anchor, RTL, cancel, reduced motion, single-pointer alternative)', () => {
  afterEach(() => {
    container?.remove();
    for (const extra of dsExtra.splice(0)) extra.remove();
  });

  it("swiping an expanded modal rail toward its edge past half its width collapses it with the swipe reason", async () => {
    const dir = 'ltr';
    const {root, el} = await dsSetup(html`<div style="display: flex; height: 400px"><md-gb-nav-rail modal expanded aria-label="Main"><md-gb-nav-rail-item selected>Home</md-gb-nav-rail-item><md-gb-nav-rail-item>Search</md-gb-nav-rail-item></md-gb-nav-rail><main style="flex: 1">Content</main></div>`, 'md-gb-nav-rail');
    const part = (selector: string) => el.shadowRoot!.querySelector<HTMLElement>(selector)!;
    const drag = dsDrag;
    const pointer = dsPointer;
    const centerOf = dsCenter;
    const reduceMotion = dsReduceMotion;
    void [root, part, drag, pointer, centerOf, reduceMotion, dir];
    const reasons: Array<string | undefined> = [];
    el.addEventListener('toggle', (e) => reasons.push((e as unknown as CustomEvent).detail.reason));
    drag(part('.nav-rail'), -(part('.nav-rail').offsetWidth * 0.8));
    await settle();
    expect(el.expanded).toBeFalse();
    expect(reasons).toEqual(['swipe']);
  });

  it("the rail follows the pointer while swiping, and returns after a short swipe or a cancel", async () => {
    // spec: interaction-gestures-94b35c
    const dir = 'ltr';
    const {root, el} = await dsSetup(html`<div style="display: flex; height: 400px"><md-gb-nav-rail modal expanded aria-label="Main"><md-gb-nav-rail-item selected>Home</md-gb-nav-rail-item></md-gb-nav-rail><main style="flex: 1">Content</main></div>`, 'md-gb-nav-rail');
    const part = (selector: string) => el.shadowRoot!.querySelector<HTMLElement>(selector)!;
    const drag = dsDrag;
    const pointer = dsPointer;
    const centerOf = dsCenter;
    const reduceMotion = dsReduceMotion;
    void [root, part, drag, pointer, centerOf, reduceMotion, dir];
    const rail = part('.nav-rail');
    const left = rail.getBoundingClientRect().left;
    drag(rail, -60, {release: false});
    await settle();
    expect(rail.getBoundingClientRect().left).toBeCloseTo(left - 60, 0);
    const {x, y} = centerOf(rail);
    pointer(rail, 'pointercancel', x - 60, y, 700);
    await settle();
    el.shadowRoot!.getAnimations().forEach((a) => a.finish());
    expect(el.expanded).toBeTrue();
    expect(rail.getBoundingClientRect().left).toBeCloseTo(left, 0);
    drag(rail, -30);
    await settle();
    expect(el.expanded).toBeTrue();
  });

  it("a fast fling dismisses the expanded modal rail however short it is", async () => {
    const dir = 'ltr';
    const {root, el} = await dsSetup(html`<div style="display: flex; height: 400px"><md-gb-nav-rail modal expanded aria-label="Main"><md-gb-nav-rail-item selected>Home</md-gb-nav-rail-item></md-gb-nav-rail><main style="flex: 1">Content</main></div>`, 'md-gb-nav-rail');
    const part = (selector: string) => el.shadowRoot!.querySelector<HTMLElement>(selector)!;
    const drag = dsDrag;
    const pointer = dsPointer;
    const centerOf = dsCenter;
    const reduceMotion = dsReduceMotion;
    void [root, part, drag, pointer, centerOf, reduceMotion, dir];
    drag(part('.nav-rail'), -30, {fast: true});
    await settle();
    expect(el.expanded).toBeFalse();
  });

  it("mirrors the swipe in right-to-left layouts: the rail closes toward the right", async () => {
    // spec: layout-bidirectionality-rtl-822768
    const dir = 'rtl';
    const {root, el} = await dsSetup(html`<div dir="${dir}" style="display: flex; height: 400px"><md-gb-nav-rail modal expanded aria-label="Main"><md-gb-nav-rail-item selected>Home</md-gb-nav-rail-item></md-gb-nav-rail><main style="flex: 1">Content</main></div>`, 'md-gb-nav-rail');
    const part = (selector: string) => el.shadowRoot!.querySelector<HTMLElement>(selector)!;
    const drag = dsDrag;
    const pointer = dsPointer;
    const centerOf = dsCenter;
    const reduceMotion = dsReduceMotion;
    void [root, part, drag, pointer, centerOf, reduceMotion, dir];
    const rail = part('.nav-rail');
    const width = rail.offsetWidth;
    drag(rail, -width * 0.8);
    await settle();
    expect(el.expanded).toBeTrue();
    drag(rail, width * 0.8);
    await settle();
    expect(el.expanded).toBeFalse();
  });
});

import {FakeCloseWatcher} from '../shared/predictive-back-harness.js';

/** The modal rail: the host owns `expanded`. */
interface ModalToggleElement extends HTMLElement {
  expanded: boolean;
}

/**
 * A close request counts as Escape for a second after an Escape press (the
 * browser reports Escape and the back gesture alike); waits that out so a
 * request is a back request.
 */
function modalOutwaitEscape() {
  return new Promise((resolve) => setTimeout(resolve, 1100));
}

/** Whether the page scroll is locked (CSS overflow of the root element). */
function modalPageLocked() {
  return getComputedStyle(document.documentElement).overflow === 'hidden';
}

async function setupModalNavRail(opts: {standard?: boolean} = {}) {
  const root = await mount(opts.standard ? html`<button id="before">Before</button><md-gb-nav-rail collapsible><md-gb-nav-rail-item label="Home"></md-gb-nav-rail-item><md-gb-nav-rail-item label="Search"></md-gb-nav-rail-item></md-gb-nav-rail>` : html`<button id="before">Before</button><md-gb-nav-rail modal collapsible><md-gb-nav-rail-item label="Home"></md-gb-nav-rail-item><md-gb-nav-rail-item label="Search"></md-gb-nav-rail-item></md-gb-nav-rail>`);
  const el = root.querySelector<ModalToggleElement>('md-gb-nav-rail')!;
  await settle();
  return {el, before: root.querySelector<HTMLElement>('#before')!};
}

async function openModalNavRail(el: ModalToggleElement) {
  el.expanded = true;
  await settle();
  await new Promise((resolve) => setTimeout(resolve, 30));
}

function isOpenModalNavRail(el: ModalToggleElement) {
  return el.expanded;
}

describe('<md-gb-nav-rail> modal surface contract (modal navigation rail; ModalSurfaceController)', () => {
  afterEach(() => container?.remove());

  it('closes on Escape with the escape reason', async () => {
    // spec: navigation-rail-4fd459
    const {el} = await setupModalNavRail();
    await openModalNavRail(el);
    const reasons: string[] = [];
    el.addEventListener('toggle', (event) => {
      const reason = (event as unknown as CustomEvent).detail.reason;
      if (reason) reasons.push(reason);
    });
    
    await press('Escape');
    await settle();
    await new Promise((resolve) => setTimeout(resolve, 30));
    expect(isOpenModalNavRail(el)).toBeFalse();
    expect(reasons).toEqual(['escape']);
  });

  it('closes on a scrim click with the scrim reason', async () => {
    // spec: navigation-rail-4fd459
    const {el} = await setupModalNavRail();
    await openModalNavRail(el);
    const reasons: string[] = [];
    el.addEventListener('toggle', (event) => {
      const reason = (event as unknown as CustomEvent).detail.reason;
      if (reason) reasons.push(reason);
    });
    
    el.shadowRoot!.querySelector<HTMLElement>('.nav-rail-scrim')!.click();
    await settle();
    await new Promise((resolve) => setTimeout(resolve, 30));
    expect(isOpenModalNavRail(el)).toBeFalse();
    expect(reasons).toEqual(['scrim']);
  });

  it('closes on a back request (close watcher) with the back reason', async () => {
    // spec: navigation-rail-4fd459, navigation-rail-0bdbd0
    const global = globalThis as {CloseWatcher?: unknown};
    const original = global.CloseWatcher;
    FakeCloseWatcher.instances = [];
    global.CloseWatcher = FakeCloseWatcher;
    try {
      const {el} = await setupModalNavRail();
      await openModalNavRail(el);
      const reasons: string[] = [];
    el.addEventListener('toggle', (event) => {
      const reason = (event as unknown as CustomEvent).detail.reason;
      if (reason) reasons.push(reason);
    });
      await modalOutwaitEscape();
      FakeCloseWatcher.active()[0].requestClose();
      // The back motion plays before the rail collapses.
      el.shadowRoot!.querySelector('.nav-rail')!.getAnimations().forEach((a) => a.finish());
      await settle();
    await new Promise((resolve) => setTimeout(resolve, 30));
      expect(isOpenModalNavRail(el)).toBeFalse();
      expect(reasons).toEqual(['back']);
    } finally {
      if (original === undefined) delete global.CloseWatcher;
      else global.CloseWatcher = original;
    }
  });

  it('moves focus into the surface when it opens and restores it when it closes', async () => {
    // spec: navigation-rail-1bdef9
    // spec: navigation-rail-1bdef9
    const {el, before} = await setupModalNavRail();
    before.focus();
    await openModalNavRail(el);
    expect(el.matches(':focus-within')).withContext('focus is inside').toBeTrue();
    
    await press('Escape');
    await settle();
    await new Promise((resolve) => setTimeout(resolve, 30));
    expect(document.activeElement).toBe(before);
  });

  it('keeps Tab and Shift+Tab inside the surface', async () => {
    // spec: navigation-rail-111de3
    const {el} = await setupModalNavRail();
    await openModalNavRail(el);
    for (let i = 0; i < 6; i++) {
      await press('Tab');
      expect(el.matches(':focus-within')).withContext(`after Tab ${i + 1}`).toBeTrue();
    }
    for (let i = 0; i < 6; i++) {
      await press('Shift+Tab');
      expect(el.matches(':focus-within')).withContext(`after Shift+Tab ${i + 1}`).toBeTrue();
    }
  });

  it('locks page scrolling while it is open, and releases the lock when it closes', async () => {
    // spec: navigation-rail-4fd459
    const {el} = await setupModalNavRail();
    expect(modalPageLocked()).toBeFalse();
    await openModalNavRail(el);
    expect(modalPageLocked()).toBeTrue();
    
    await press('Escape');
    await settle();
    await new Promise((resolve) => setTimeout(resolve, 30));
    expect(modalPageLocked()).toBeFalse();
  });

  it('standard variant: no scroll lock, no focus move, ignores Escape', async () => {
    // spec: navigation-rail-4e0bd5
    // spec: navigation-rail-4fd459
    const {el, before} = await setupModalNavRail({standard: true});
    before.focus();
    await openModalNavRail(el);
    expect(modalPageLocked()).withContext('no scroll lock').toBeFalse();
    expect(document.activeElement).withContext('focus stays').toBe(before);
    await press('Escape');
    await settle();
    expect(isOpenModalNavRail(el)).withContext('Escape does not close it').toBeTrue();
  });
});
